var buyer = $input.first().json;
var errors = [];

if (!buyer.name || buyer.name.trim() === '') {
  errors.push('name is required');
}
if (!buyer.phone) {
  errors.push('phone is required');
}

if (!buyer.criteria) {
  errors.push('criteria object is required');
} else {
  if (!buyer.criteria.markets || buyer.criteria.markets.length === 0) {
    errors.push('criteria.markets must have at least 1 market');
  }
  if (!buyer.criteria.propertyTypes || buyer.criteria.propertyTypes.length === 0) {
    errors.push('criteria.propertyTypes must have at least 1 type');
  }
  if (!buyer.criteria.strategies || buyer.criteria.strategies.length === 0) {
    errors.push('criteria.strategies must have at least 1 strategy');
  }
  if (!buyer.criteria.priceMin || buyer.criteria.priceMin <= 0) {
    errors.push('criteria.priceMin must be > 0');
  }
  if (!buyer.criteria.priceMax || buyer.criteria.priceMax <= buyer.criteria.priceMin) {
    errors.push('criteria.priceMax must be > priceMin');
  }
  if (!buyer.criteria.monthlyCapacity || buyer.criteria.monthlyCapacity <= 0) {
    errors.push('criteria.monthlyCapacity must be > 0');
  }

  var validStrategies = ['Flip', 'BRRRR', 'Rental', 'Wholesale'];
  if (buyer.criteria.strategies) {
    for (var i = 0; i < buyer.criteria.strategies.length; i++) {
      if (validStrategies.indexOf(buyer.criteria.strategies[i]) === -1) {
        errors.push('Invalid strategy: ' + buyer.criteria.strategies[i]);
      }
    }
  }

  var validPropertyTypes = ['SFR', 'Duplex', 'Multi', 'Land', 'Commercial'];
  if (buyer.criteria.propertyTypes) {
    for (var i = 0; i < buyer.criteria.propertyTypes.length; i++) {
      if (validPropertyTypes.indexOf(buyer.criteria.propertyTypes[i]) === -1) {
        errors.push('Invalid propertyType: ' + buyer.criteria.propertyTypes[i]);
      }
    }
  }
}

return {
  json: {
    valid: errors.length === 0,
    errors: errors,
    buyer: buyer
  }
};

var buyer = $input.first().json.buyer;
var phone = buyer.phone;

var digits = phone.replace(/\D/g, '');

if (digits.length === 10) {
  digits = '1' + digits;
}

if (digits.length === 11 && digits[0] === '1') {
  phone = '+' + digits;
} else {
  phone = '+' + digits;
}

return {
  json: {
    buyer: buyer,
    normalizedPhone: phone
  }
};

var existingBuyer = $input.first().json.data;
var response = null;

switch (existingBuyer.status) {
  case 'dnc':
    response = {
      statusCode: 403,
      body: { success: false, error: 'Buyer is on DNC list. They must text START to reactivate.', buyerId: existingBuyer._id, status: 'dnc' }
    };
    break;
  case 'pending_optin':
    response = {
      statusCode: 200,
      body: { success: true, buyerId: existingBuyer._id, status: 'pending_optin', note: 'Opt-in SMS resent. Buyer must reply YES.' },
      resendOptin: true,
      closeLeadId: existingBuyer.closeLeadId
    };
    break;
  case 'inactive':
  case 'dormant':
    response = {
      statusCode: 200,
      body: { success: true, buyerId: existingBuyer._id, status: 'pending_optin', note: 'Buyer reactivated. Opt-in SMS sent.' },
      resendOptin: true,
      closeLeadId: existingBuyer.closeLeadId
    };
    break;
  default:
    response = {
      statusCode: 200,
      body: { success: true, buyerId: existingBuyer._id, status: existingBuyer.status, note: 'Criteria updated for existing buyer.' }
    };
}

return { json: response };

